def fix(grid, anom=3):
    h,w=len(grid),len(grid[0])
    g=[row[:] for row in grid]
    parts=[lambda i,j:(h-1-i,j), lambda i,j:(i,w-1-j), lambda i,j:(h-1-i,w-1-j)]
    changed=True
    while changed:
        changed=False
        for i in range(h):
            for j in range(w):
                if g[i][j]==anom:
                    for p in parts:
                        a=p(i,j); v=g[a[0]][a[1]]
                        if v!=anom:
                            g[i][j]=v; changed=True; break
    return g
